<?php
require '/app/api/life/store.php';require '/app/api/life/calendar-export.php';
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec(file_get_contents('/app/api/life/schema.sql'));$store=new LifeStore($db);$store->initialize('thinking-test-passphrase');$checks=0;
function ok($condition){global $checks;if(!$condition)throw new Exception('Check failed: '.$checks);$checks++;}
function change($a,$args=[],$role='owner'){global $store;return $store->mutate($store->read()['version'],$a,$args,$role);}
$d=change('note.save',['title'=>'First idea','body'=>'Private context','kind'=>'idea','group'=>'Life']);$id=$d['state']['notes'][0]['id'];ok(count($d['state']['notes'])===1);
$d=change('note.convert',['id'=>$id,'target'=>'goal']);ok($d['state']['goals'][0]['sourceNoteId']===$id);try{change('note.convert',['id'=>$id,'target'=>'goal']);ok(false);}catch(LifeError $e){ok($e->status===422);}
$d=change('note.archive',['id'=>$id]);ok($d['state']['notes'][0]['archived']);$d=change('note.restore',['id'=>$id]);ok(!$d['state']['notes'][0]['archived']);
$d=change('map.save',['title'=>'Goal','kind'=>'goal','recordId'=>$d['state']['goals'][0]['id'],'x'=>50,'y'=>60]);$a=$d['state']['mapNodes'][0]['id'];$d=change('map.save',['title'=>'Question','kind'=>'question','x'=>300,'y'=>80]);$b=$d['state']['mapNodes'][1]['id'];$d=change('map.connect',['from'=>$a,'to'=>$b]);ok(count($d['state']['mapEdges'])===1);$d=change('map.archive',['id'=>$a]);ok(count($d['state']['mapEdges'])===0);
$list=$d['state']['lists'][0]['id'];foreach(['One','Two'] as $title)$d=change('task.save',['title'=>$title,'listId'=>$list,'dueDate'=>'2026-10-12']);[$one,$two]=$d['state']['tasks'];$d=change('task.dependencies',['id'=>$one['id'],'ids'=>[$two['id']]]);ok($d['state']['tasks'][0]['dependencies'][0]===$two['id']);try{change('task.dependencies',['id'=>$two['id'],'ids'=>[$one['id']]]);ok(false);}catch(LifeError $e){ok($e->status===422);}
$d=change('template.save',['kind'=>'board','name'=>'Focus','lists'=>['Ideas','Doing','Done']]);$d=change('template.apply',['id'=>$d['state']['templates'][0]['id']]);ok(count($d['state']['boards'])===2);ok(count($d['state']['activity'])>=10);$ics=life_ical($d['state']);ok(str_contains($ics,'DTSTART;VALUE=DATE:20261012'));ok(str_contains($ics,"END:VCALENDAR\r\n"));try{change('note.save',['title'=>'No'], 'partner');ok(false);}catch(LifeError $e){ok($e->status===403);}
$backup=json_encode($store->read()['state']);$db->prepare('UPDATE life_board SET state=? WHERE id=1')->execute([$backup]);ok($store->read()['state']===$d['state']);$store->throttle('test-ip');ok((int)$db->query('SELECT COUNT(*) FROM life_login_attempt')->fetchColumn()===1);$store->clearThrottle('test-ip');ok((int)$db->query('SELECT COUNT(*) FROM life_login_attempt')->fetchColumn()===0);echo "$checks thinking checks passed\n";
